function tok(expr) {
  const tokens = [];
  let i = 0;
  while (i < expr.length) {
    if (/\s/.test(expr[i])) { i++; continue; }
    if (/\d/.test(expr[i])) {
      let num = '';
      while (i < expr.length && /\d/.test(expr[i])) num += expr[i++];
      tokens.push({type:'number',value:num});
    } else {
      const map = {'+':'plus','-':'minus','*':'star','/':'slash','(':'lparen',')':'rparen'};
      tokens.push({type:map[expr[i]],value:expr[i++]});
    }
  }
  return tokens;
}

test('evaluates simple addition', () => {
  expect(evaluate(parse(tok('1 + 2')))).toBe(3);
});

test('respects operator precedence', () => {
  expect(evaluate(parse(tok('1 + 2 * 3')))).toBe(7);
});

test('evaluates parentheses override precedence', () => {
  expect(evaluate(parse(tok('(1 + 2) * 3')))).toBe(9);
});

test('evaluates subtraction and division', () => {
  expect(evaluate(parse(tok('10 - 4 / 2')))).toBe(8);
});

// __hidden__
test('evaluates nested parentheses', () => {
  expect(evaluate(parse(tok('((2 + 3) * (1 + 1))')))).toBe(10);
});

