export function parse(tokens) {
  let pos = 0;

  function peek() { return tokens[pos]; }
  function consume() { return tokens[pos++]; }

  function parseExpr() { return parseAddSub(); }

  function parseAddSub() {
    let left = parseMulDiv();
    while (peek() && (peek().type === 'plus' || peek().type === 'minus')) {
      const op = consume().value;
      const right = parseMulDiv();
      left = { type: 'binary', op, left, right };
    }
    return left;
  }

  function parseMulDiv() {
    let left = parsePrimary();
    while (peek() && (peek().type === 'star' || peek().type === 'slash')) {
      const op = consume().value;
      const right = parsePrimary();
      left = { type: 'binary', op, left, right };
    }
    return left;
  }

  function parsePrimary() {
    const t = peek();
    if (t.type === 'number') {
      consume();
      return { type: 'number', value: Number(t.value) };
    }
    if (t.type === 'lparen') {
      consume();
      const node = parseExpr();
      consume();
      return node;
    }
    throw new Error('Unexpected token: ' + t.type);
  }

  return parseExpr();
}

export function evaluate(ast) {
  if (ast.type === 'number') return ast.value;
  const l = evaluate(ast.left);
  const r = evaluate(ast.right);
  if (ast.op === '+') return l + r;
  if (ast.op === '-') return l - r;
  if (ast.op === '*') return l * r;
  if (ast.op === '/') return l / r;
  throw new Error('Unknown op: ' + ast.op);
}
